import { test, expect } from '@playwright/test';

test.describe('Dashboard Sidebar to Bottom Nav Bar on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should transform sidebar to bottom nav bar on mobile viewport', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 820 });

    // Verify sidebar is visible and contains navigation links
    const sidebar = page.getByRole('navigation', { name: /dashboard navigation/i });
    await expect(sidebar).toBeVisible();

    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const profileLink = page.getByRole('link', { name: /profile/i });
    await expect(profileLink).toBeVisible();

    // Verify sidebar has the correct mobile class
    const sidebarElement = page.locator('[data-testid="sidebar-container"]');
    await expect(sidebarElement).toHaveClass(/mobile-sidebar/);

    // Verify bottom nav bar is visible
    const bottomNav = page.locator('[data-testid="bottom-nav"]');
    await expect(bottomNav).toBeVisible();

    // Verify bottom nav bar contains navigation links
    const bottomHome = page.getByRole('link', { name: /home/i });
    await expect(bottomHome).toBeVisible();

    const bottomProfile = page.getByRole('link', { name: /profile/i });
    await expect(bottomProfile).toBeVisible();

    // Verify sidebar is hidden on mobile
    await expect(sidebarElement).not.toBeVisible();
  });

  test('should revert to sidebar on desktop viewport and handle navigation', async ({ page }) => {
    // Set viewport to desktop size
    await page.setViewportSize({ width: 1200, height: 900 });

    // Verify sidebar is visible and bottom nav is hidden
    const sidebar = page.getByRole('navigation', { name: /dashboard navigation/i });
    await expect(sidebar).toBeVisible();

    const bottomNav = page.locator('[data-testid="bottom-nav"]');
    await expect(bottomNav).not.toBeVisible();

    // Verify sidebar has desktop class
    const sidebarElement = page.locator('[data-testid="sidebar-container"]');
    await expect(sidebarElement).toHaveClass(/desktop-sidebar/);

    // Verify navigation links are in sidebar
    const homeLink = page.getByRole('link', { name: /home/i });
    await expect(homeLink).toBeVisible();

    const profileLink = page.getByRole('link', { name: /profile/i });
    await expect(profileLink).toBeVisible();

    // Click on a sidebar link to verify navigation
    await homeLink.click();
    await expect(page).toHaveURL(/.*\/dashboard\/home/);

    // Verify bottom nav is still hidden
    await expect(bottomNav).not.toBeVisible();
  });
});
